; >S:IRQ; PUT "IRQ";;*********************;; ALL THE IRQ ROUTINES;;*********************;;RASVAL;.BYTE $C1,$00;SETIRQ;; SET UP IRQ'S;SEI;LDA #<SERVSTA $0314LDA #>SERVSTA $0315;LDA #%00000010STA IRQMSK;; ENABLE IRQ'S FROM :-;; RASTER;; NO HASSLE FROM TIMER 2 IN THIS !;LDA RASVALSTA RASCOM;LDA #0STA INTYPE;; SET RASTER COMPARE;CLI;RTS;;-------------------------------;SERV;;************************;;IRQ COMES HERE - WOW !!!;;************************;LDA IRQREGSTA IRQREG ;* RESET BITS;LDA INTYPE ;* RASTER NUMBEREOR #1STA INTYPE;;*************************;; RASTER SERVICE ROUTINE;;*************************;LDA SLPHALDA SL+1PHALDA CLPHALDA CL+1PHA;; SAVE 'XY' VARIABLES;LDA INTYPEBNE NORAS1;JMP RAST1;NORAS1;JMP RAST2;NORAS2;;;;;;************;;  IRQ EXIT;;************;IRQEND;PLASTA CL+1PLASTA CLPLASTA SL+1PLASTA SL;LDX INTYPELDA RASVAL,XSTA RASCOM;PLATAYPLATAXPLARTI;;;;;.END 